import { FunctionalComponent} from 'preact';
import { useEffect, useRef } from 'preact/hooks';
import { useSelector } from 'react-redux';
import { selectUiMode } from '../../../../store/selectors';
import { Quote as IQuote } from '../../slice/types';
import styles from './styles.module.scss';

const ASSETS_HOST = `https://assets.oceanhero.today/extension/extension-story/assets`;

interface QuoteProps {
  message: IQuote;
}

const QuoteStory: FunctionalComponent<QuoteProps> = ({
  message,
}: QuoteProps) => {
  const mode = useSelector(selectUiMode);
  const textRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (textRef.current !== null) {
      const { classList } = textRef.current;
      const textWidth = Math.floor(
        textRef.current.getBoundingClientRect().width
      );

      textWidth <= 430 && classList.add('text-lg');
    }
  }, []);

  const fontSize = (() => {
    if (message.text.length < 60) return 32;
  })();

  return (
    <div className={`${styles.quoteStory} ${styles[mode + 'Quote']}`}>
      <div className={styles.quoteWrapper}>
        <div className={styles.leftQuote}>“</div>
        <div className={styles.quoteText} ref={textRef}>
          <span dangerouslySetInnerHTML={{ __html: message.text }} style={fontSize ? { fontSize, lineHeight: `${fontSize}px` } : {}} />
          {message.emoji && (
            <img
              className={styles.quoteEmoji}
              src={`${ASSETS_HOST}/emoji/${message.emoji}`}
              onLoad={(e): void => {
                // @ts-ignore
                e.target.style.display = 'inline-flex';
              }}
            />
          )}
        </div>
        <div className={styles.rightQuote}>”</div>
      </div>
      {message.author && (
        <div className={styles.quoteAuthor}>– {message.author}</div>
      )}
    </div>
  );
};

export default QuoteStory;
