import { Fragment, FunctionalComponent} from 'preact';
import { useState } from 'preact/hooks';
import { useSelector } from 'react-redux';
import { selectUiMode } from '../../../../store/selectors';
import { Image as IImage } from '../../slice/types';
import closeIcon from './assets/close.svg';
import styles from './styles.module.scss';

const ASSETS_HOST = `https://assets.oceanhero.today/extension/extension-story/assets`;

interface ImageProps {
  message: IImage;
}

const ImageStory: FunctionalComponent<ImageProps> = ({
  message,
}: ImageProps) => {
  const uiMode = useSelector(selectUiMode);
  const [showDialog, setShowDialog] = useState(false);
  const [loops, setLoops] = useState(1);
  const isMp4 = message.imgSrc.endsWith('mp4');
  const videoSrc = message.imgSrc.includes('://')
    ? message.imgSrc
    : `${ASSETS_HOST}/${message.imgSrc}`;

  const handleVideoLoop = (el: HTMLVideoElement): void => {
    if (message?.loops) {
      setLoops((v) => ++v);

      if (loops !== message?.loops) el.play();
      return;
    }

    el.play();
  };

  return (
    <Fragment>
      <div
        className={showDialog ? styles.backdrop : ''}
        onClick={(): void => setShowDialog(false)}
      />
      <div className={styles.imageStoryWrapper}>
        <div className={styles.image}>
          {isMp4 ? (
            <video
              className={styles[uiMode]}
              src={videoSrc}
              onClick={(): void => setShowDialog(true)}
              onEnded={(e): void =>
                handleVideoLoop(e.target as HTMLVideoElement)
              }
              muted
              autoPlay
            />
          ) : (
            <img
              className={styles[uiMode]}
              src={`${ASSETS_HOST}/${message.imgSrc}`}
              onClick={(): void => setShowDialog(true)}
              alt={message.text}
            />
          )}
        </div>
        <div className={`${styles.description} ${styles[uiMode]}`}>
          <span className={styles.text}>{message.text}</span>
          {message?.button?.link && (
            <a href={message.button.link} className={styles.descriptionBtn}>
              {message.button.name}
            </a>
          )}
        </div>

        {showDialog && (
          <dialog
            className={`${styles.dialog} ${styles[uiMode]}`}
            style={{ position: 'absolute' }}
            open
          >
            <div className={styles.dialogContent}>
              <img
                src={closeIcon}
                alt="close"
                className={styles.closeBtn}
                onClick={(): void => setShowDialog(false)}
              />
              {isMp4 ? (
                <video src={videoSrc} muted loop autoPlay />
              ) : (
                <img
                  className={styles.dialogImage}
                  src={`${ASSETS_HOST}/${message.imgSrc}`}
                  alt={message.text}
                />
              )}
              <div className={styles.dialogDescription}>
                <span className={styles.text}>{message.text}</span>
                {message?.button?.link && (
                  <a
                    href={message.button.link}
                    className={styles.descriptionBtn}
                  >
                    {message.button.name}
                  </a>
                )}
              </div>
            </div>
          </dialog>
        )}
      </div>
    </Fragment>
  );
};

export default ImageStory;
