import { FunctionalComponent} from 'preact';
import { useSelector } from 'react-redux';
import QuoteStory from './components/Quote';
import VideoStory from './components/Video';
import ImageStory from './components/Image';
import Fireworks from '../../../shared/Fireworks';
import { selectShowFireforks } from './slice';
import { StoryMessage } from './slice/types';
import styles from './styles.module.scss';

const COMPONENTS = {
  quote: QuoteStory,
  image: ImageStory,
  video: VideoStory,
};

interface StoryProps {
  shown: { message: StoryMessage };
}

const Story: FunctionalComponent<StoryProps> = ({ shown }: StoryProps) => {
  const showFireworks = useSelector(selectShowFireforks);
  const StoryComponent = COMPONENTS[shown.message?.type];

  if (!StoryComponent) return null;

  return (
    <div>
      {showFireworks && <Fireworks />}
      <div className={styles.storyContainer}>
        {/* eslint-disable-next-line */}
        <StoryComponent message={shown.message as any} />
      </div>
    </div>
  );
};

export default Story;
