import { FunctionalComponent } from 'preact';
import { useState } from 'preact/hooks';
import PlayArrow from '@material-ui/icons/PlayArrow';

import ModalTemplate from './Modal';

// import ReactPlayer from 'react-player/youtube';
// import playIcon from './assets/playIcon.svg';

import { Video as IVideo } from '../../slice/types';
import styles from './styles.module.scss';

const ASSETS_HOST = `https://assets.oceanhero.today/extension/extension-story/assets`;

interface VideoProps {
  message: IVideo;
}

const VideoStory: FunctionalComponent<VideoProps> = ({
  message,
}: VideoProps) => {
  const [playerLoaded, setPlayerLoaded] = useState(false);

  const startPlayer = () => {
    setPlayerLoaded(true);
  };

  const dimensions = window.innerHeight < 700 ?
    { height: 200, width: 355 } :
    { height: 220, width: 390 };

  const handleClose = () => {
    setPlayerLoaded(false);
  };

  return (
    <>
      <div
        className={styles.playerWrapper}
        onClick={startPlayer}
      >
        <img
          src={`${ASSETS_HOST}/${message.coverSrc}`}
          alt='Doodle' height={dimensions.height}
        />

        <button className={styles.playButton} style={message.buttonStyles || {}}>
          <PlayArrow />
        </button>
      </div>

      {playerLoaded && (
        <ModalTemplate onClose={handleClose}>
          <iframe
            className={styles.videoIframe}
            src={message.videoUrl}
            // onLoad={startedPlaying('success')}
            // onError={startedPlaying('error')}
            title="Doodle"
            frameBorder="0"
            allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
            allowFullScreen
          />
        </ModalTemplate>
      )}
    </>
  )

  /*
  return (
    <div className={styles.playerWrapper}>
      <ReactPlayer
        url={message.videoUrl}
        playing={playerLoaded}
        light={`${ASSETS_HOST}/${message.coverSrc}`}
        playIcon={
          <img className={styles.playButton} src={playIcon} alt="play icon" />
        }
        width={355}
        height={200}
        onClick={startPlayer}
      />
    </div>
  );
   */
};

export default VideoStory;
